// Logs → Waiting tab — WHO IS BLOCKED ON A HUMAN (#4015), AS GRAPH SOURCE (epic #3604).
//
// The queue `bsc logs waiting` answers, given a screen for the first time. Until now nothing could
// SHOW it: not the user, not the director, not an agent. It is the most urgent thing in a fleet and
// the easiest to miss.
//
// This is also the tab the deleted Flow tab was reaching for. Flow rendered "which sessions are
// parked on a dependency (#199)", a mechanism removed in #1039, so it could only ever render its
// idle state. The live question underneath it — who is stuck — is this.
//
// OLDEST FIRST IS THE CONTRACT, not a default. This is a queue, and the longest-waiting session is
// the one to clear first; the rows arrive in that order and are NOT re-sorted here. Every other log
// surface in the app is newest-first, so the temptation to "make it consistent" is real and wrong.
//
// Four ways to be blocked, across two logs:
//   wait        coord.log     bsc-wait  — parked for the user
//   ask         coord.log     bsc-ask   — a question for the director (supersedes a plain wait)
//   request     coord.log     #4001     — a change request, keyed by id, resolved by that id
//   permission  activity.log  #4005     — stopped at a permission prompt; carries NO detail text
//
// Preview note: `logsWaiting` is app-internal (unresolvable in this sandbox), so the row type and a
// sample queue are inlined below. Every prop still overrides the sample when composed by LogsWorkspace.
import { StatTile } from "@/shared/ui/data/StatTile";
import { Row } from "@/shared/ui/layout/Row";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";

interface WaitingRow { pane: string; kind: string; detail: string; at: number; id: string }
type KindFilter = "all" | "wait" | "ask" | "request" | "permission";

const NOW = 1700000000000;
const SAMPLE_ROWS: WaitingRow[] = [
  { pane: "cli-typer:typing-engine", kind: "wait", detail: "waiting for commons-landed signal: director is landing contracts on main (Phase 0).", at: NOW - 86400000 * 3, id: "" },
  { pane: "network-monitor:host-operations-adapter", kind: "ask", detail: "ObservationPoint has only telemetry-specific variants; recommend adding adapter-native ones. Using DnsResolver as a clearly-wrong placeholder meanwhile.", at: NOW - 3600000 * 5, id: "" },
  { pane: "studio-code:mobile-studio-shell", kind: "request", detail: "delete the stale ORPHANS entry — outside this stream's write scope and now blocking the test gate", at: NOW - 3600000 * 2, id: "2" },
  { pane: "design-studio:designer", kind: "permission", detail: "", at: NOW - 600000, id: "" },
];

/** How long a row has been waiting, coarsely — the only number that matters in a queue. */
export function waitAge(at: number, now: number): string {
  const ms = Math.max(0, now - at);
  const m = Math.floor(ms / 60000);
  if (m < 1) return "just now";
  if (m < 60) return m + "m";
  const h = Math.floor(m / 60);
  if (h < 24) return h + "h";
  return Math.floor(h / 24) + "d";
}

/** A row is STALE once it has waited a day — long enough that nobody is coming for it. */
export function isStale(at: number, now: number): boolean {
  return now - at >= 86400000;
}

/** Filter by kind. `all` shows everything; the rows keep their oldest-first order either way. */
export function filterWaiting(rows: WaitingRow[], kind: KindFilter): WaitingRow[] {
  return kind === "all" ? rows : rows.filter((r) => r.kind === kind);
}

/** How many rows of each kind — the chip counts and the stat tiles read the same tally. */
export function waitingCounts(rows: WaitingRow[]): Record<string, number> {
  const c: Record<string, number> = { wait: 0, ask: 0, request: 0, permission: 0 };
  for (const r of rows) if (r.kind in c) c[r.kind] += 1;
  return c;
}

const KIND_COLOR: Record<string, string> = {
  wait: "var(--state-wait)",
  ask: "var(--accent)",
  request: "var(--info, var(--accent))",
  permission: "var(--danger)",
};

/** What each kind actually needs from a person — the row's whole reason to exist. */
const KIND_NEED: Record<string, string> = {
  wait: "parked for you",
  ask: "a question for the director",
  request: "a change request to resolve",
  permission: "stopped at a permission prompt",
};

export interface WaitingTabProps {
  rows?: WaitingRow[];
  kind?: KindFilter;
  setKind?: (k: KindFilter) => void;
  /** Injected so the age column is deterministic in a test and in the preview. */
  now?: number;
}

export function WaitingTab({
  rows = SAMPLE_ROWS, kind = "all", setKind = () => {}, now = NOW,
}: WaitingTabProps) {
  const shown = filterWaiting(rows, kind);
  const counts = waitingCounts(rows);
  const oldest = rows.length > 0 ? rows[0] : null; // rows arrive oldest-first
  const stale = rows.filter((r) => isStale(r.at, now)).length;

  const chip = (k: KindFilter, label: string, n?: number) => {
    const on = kind === k;
    return (
      <Box as="span" key={k} onClick={() => setKind(k)} style={{
        display: "inline-flex", alignItems: "center", gap: 6, padding: "4px 10px", borderRadius: 999, cursor: "pointer", fontSize: 11,
        border: on ? "1px solid var(--accent)" : "1px solid var(--border-soft)", background: on ? "var(--bg-elev2)" : "transparent", color: on ? "var(--fg)" : "var(--fg-muted)",
      }}>
        <Box as="span" bg={k === "all" ? "var(--fg-dim)" : KIND_COLOR[k]} radius={99} style={{ width: 6, height: 6 }} />
        {label}{n !== undefined && <Text as="span" tone="dim" style={{ marginLeft: 2 }}>{n}</Text>}
      </Box>
    );
  };

  const COLS = "70px 1fr 108px 2fr";
  return (
    <Box style={{ display: "flex", flexDirection: "column", width: "100%" }}>
      <Box style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(130px, 1fr))", gap: 10, marginBottom: 14 }}>
        <StatTile k="blocked" v={rows.length} sub="sessions waiting on a person" />
        <StatTile k="questions" v={counts.ask + counts.request} tone="accent" sub="asks + change requests" />
        <StatTile k="at a prompt" v={counts.permission} tone="danger" sub="stopped mid-tool" />
        <StatTile k="over a day" v={stale} tone={stale > 0 ? "danger" : undefined} sub={oldest ? "oldest " + waitAge(oldest.at, now) : "nothing stale"} />
      </Box>

      <Row align="center" gap={10} wrap style={{ marginBottom: 12 }}>
        <Text as="span" mono size={10} tone="dim" style={{ textTransform: "uppercase", letterSpacing: ".05em" }}>kind</Text>
        <Row gap={6} align="stretch">
          {chip("all", "all")}
          {chip("wait", "parked", counts.wait)}
          {chip("ask", "asking", counts.ask)}
          {chip("request", "requests", counts.request)}
          {chip("permission", "prompts", counts.permission)}
        </Row>
        <Box style={{ flex: 1 }} />
        <Text as="span" mono size={10} tone="dim">oldest first — this is a queue</Text>
      </Row>

      {rows.length === 0 ? (
        <EmptyState
          iconVariant="dashed" icon="✓" size="sm"
          title="Nothing is waiting on you"
          description="Sessions appear here when a worker parks for you, asks the director a question, files a change request, or stops at a permission prompt."
        />
      ) : (
        <Box border="soft" radius={7} style={{ overflow: "hidden" }}>
          <Box style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, padding: "7px 12px", background: "var(--bg-elev2)", borderBottom: "1px solid var(--border-soft)", fontSize: 9.5, color: "var(--fg-dim)", textTransform: "uppercase", letterSpacing: ".05em" }}>
            <Box as="span">waiting</Box><Box as="span">pane</Box><Box as="span">kind</Box><Box as="span">what it needs</Box>
          </Box>
          {shown.length === 0 && (
            <Text as="div" mono tone="dim" size={11.5} style={{ padding: "18px 14px" }}>
              Nothing of this kind is waiting — {rows.length} other {rows.length === 1 ? "session is" : "sessions are"} still blocked.
            </Text>
          )}
          {shown.map((r, i) => (
            <Box key={r.pane + ":" + r.kind + ":" + r.id + ":" + r.at} style={{ display: "grid", gridTemplateColumns: COLS, gap: 10, alignItems: "baseline", padding: "8px 12px", fontSize: 11, background: i % 2 ? "var(--bg-panel)" : "var(--bg-elev)" }}>
              <Text as="span" mono size={10.5} style={{ color: isStale(r.at, now) ? "var(--danger)" : "var(--fg-dim)" }}>{waitAge(r.at, now)}</Text>
              <Text as="span" tone="muted" style={{ whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{r.pane}</Text>
              <Box as="span" style={{ display: "inline-flex", alignItems: "center", gap: 6 }}>
                <Box as="span" bg={KIND_COLOR[r.kind] ?? "var(--fg-dim)"} radius={99} style={{ width: 7, height: 7 }} />
                <Text as="span" mono size={10.5}>{r.kind}</Text>
                {r.id !== "" && <Text as="span" mono size={10} tone="dim" title="resolve it with the plan request verb">#{r.id}</Text>}
              </Box>
              {/* A permission prompt carries no text at all. Rendering the empty string would make the
                  most urgent row in the table look like a blank line, so it states its own condition. */}
              {r.detail !== "" ? (
                <Text as="span" tone="muted" style={{ lineHeight: 1.5 }}>{r.detail}</Text>
              ) : (
                <Text as="span" tone="dim" style={{ fontStyle: "italic" }}>{KIND_NEED[r.kind] ?? "no detail recorded"}</Text>
              )}
            </Box>
          ))}
        </Box>
      )}
    </Box>
  );
}

