// The Waiting tab — the blocked-on-a-human queue (#4015).
//
// Carried ON the record, so it runs against the copy that actually mounts (`.bsc-records/`), not a
// second file that could drift from it.
import { describe, it, expect, vi } from "vitest";
import { render, screen, fireEvent, within } from "@testing-library/react";
import { WaitingTab, waitAge, isStale, filterWaiting, waitingCounts } from "./WaitingTab";

const NOW = 1700000000000;
const MIN = 60000;
const HOUR = 60 * MIN;
const DAY = 24 * HOUR;

/** Oldest-first, exactly as `bsc logs waiting` hands them over. */
const QUEUE = [
  { pane: "alpha:engine", kind: "wait", detail: "parked for the commons signal", at: NOW - DAY * 3, id: "" },
  { pane: "alpha:adapter", kind: "ask", detail: "which ObservationPoint variant?", at: NOW - HOUR * 5, id: "" },
  { pane: "beta:shell", kind: "request", detail: "delete the stale ORPHANS entry", at: NOW - HOUR * 2, id: "7" },
  { pane: "studio:designer", kind: "permission", detail: "", at: NOW - MIN * 10, id: "" },
];

describe("waitAge / isStale", () => {
  it("degrades from minutes to days, and floors rather than rounds", () => {
    expect(waitAge(NOW - 30000, NOW)).toBe("just now"); // under a minute
    expect(waitAge(NOW - MIN * 14, NOW)).toBe("14m");
    expect(waitAge(NOW - MIN * 59, NOW)).toBe("59m");
    expect(waitAge(NOW - HOUR, NOW)).toBe("1h");
    expect(waitAge(NOW - HOUR * 23, NOW)).toBe("23h");
    expect(waitAge(NOW - DAY, NOW)).toBe("1d");
    expect(waitAge(NOW - DAY * 3 - HOUR * 5, NOW)).toBe("3d"); // floors, so it never over-reports
  });

  it("never renders a negative age from a clock skew", () => {
    // The `at` comes from a log line written by another process; a future timestamp is possible and
    // "-4m" would read as a bug in the queue rather than in the clock.
    expect(waitAge(NOW + HOUR, NOW)).toBe("just now");
  });

  it("calls a row stale at exactly a day, not after it", () => {
    expect(isStale(NOW - DAY + 1, NOW)).toBe(false);
    expect(isStale(NOW - DAY, NOW)).toBe(true);
  });
});

describe("filterWaiting / waitingCounts", () => {
  it("filters by kind and PRESERVES the oldest-first order", () => {
    // The order is the queue's contract. A filter that re-sorted would silently change which row a
    // human clears first.
    expect(filterWaiting(QUEUE, "all").map((r) => r.pane)).toEqual(QUEUE.map((r) => r.pane));
    expect(filterWaiting(QUEUE, "ask").map((r) => r.pane)).toEqual(["alpha:adapter"]);
    expect(filterWaiting(QUEUE, "permission")).toHaveLength(1);
  });

  it("tallies every kind, including the ones at zero", () => {
    // A zero must be a zero, not an absent key: the chips render `counts.ask` directly.
    expect(waitingCounts(QUEUE)).toEqual({ wait: 1, ask: 1, request: 1, permission: 1 });
    expect(waitingCounts([])).toEqual({ wait: 0, ask: 0, request: 0, permission: 0 });
  });

  it("ignores a kind the frontend does not know", () => {
    // The kinds come from Rust as a plain string; a new one added there must not crash the tally.
    const rows = [...QUEUE, { pane: "x", kind: "invented", detail: "", at: NOW, id: "" }];
    expect(waitingCounts(rows).wait).toBe(1);
    expect(Object.keys(waitingCounts(rows))).toHaveLength(4);
  });
});

describe("WaitingTab — the queue", () => {
  it("renders every blocked session, oldest first", () => {
    const { container } = render(<WaitingTab rows={QUEUE} now={NOW} />);
    const panes = Array.from(container.querySelectorAll("span")).map((n) => n.textContent);
    const order = QUEUE.map((r) => r.pane).filter((p) => panes.includes(p));
    expect(order).toEqual(["alpha:engine", "alpha:adapter", "beta:shell", "studio:designer"]);
    // …and the DOM order matches, not merely the presence.
    const html = container.innerHTML;
    expect(html.indexOf("alpha:engine")).toBeLessThan(html.indexOf("alpha:adapter"));
    expect(html.indexOf("alpha:adapter")).toBeLessThan(html.indexOf("beta:shell"));
    expect(html.indexOf("beta:shell")).toBeLessThan(html.indexOf("studio:designer"));
  });

  it("a PERMISSION row reads as a real entry, not a blank line", () => {
    // It is the only kind that carries no detail text, and it is the most urgent one. Rendering the
    // empty string would leave the most important row looking like an empty cell.
    render(<WaitingTab rows={QUEUE} now={NOW} />);
    expect(screen.getByText("stopped at a permission prompt")).toBeInTheDocument();
  });

  it("a REQUEST row surfaces its id — that is what resolves it", () => {
    render(<WaitingTab rows={QUEUE} now={NOW} />);
    expect(screen.getByText("#7")).toBeInTheDocument();
  });

  it("shows each row's age, and flags the ones over a day", () => {
    render(<WaitingTab rows={QUEUE} now={NOW} />);
    expect(screen.getByText("3d")).toBeInTheDocument();
    expect(screen.getByText("5h")).toBeInTheDocument();
    expect(screen.getByText("10m")).toBeInTheDocument();
    // The stat tile counts the stale ones and names the oldest.
    expect(screen.getByText("oldest 3d")).toBeInTheDocument();
  });

  it("an EMPTY queue is an empty STATE, not an empty table", () => {
    // A bare header row over nothing reads as "the feature is broken"; this reads as "you are clear".
    const { container } = render(<WaitingTab rows={[]} now={NOW} />);
    expect(screen.getByText("Nothing is waiting on you")).toBeInTheDocument();
    expect(container.textContent).not.toContain("what it needs"); // no table header
  });

  it("filtering to a kind with no rows explains itself rather than looking empty", () => {
    // The distinction that matters: nothing of THIS kind, versus nothing at all. Conflating them
    // would tell a user with three blocked sessions that they are clear.
    render(<WaitingTab rows={QUEUE} kind="wait" now={NOW} />);
    const onlyWait = filterWaiting(QUEUE, "wait");
    expect(onlyWait).toHaveLength(1);
    render(<WaitingTab rows={[QUEUE[3]]} kind="ask" now={NOW} />);
    expect(screen.getByText(/Nothing of this kind is waiting/)).toBeInTheDocument();
    expect(screen.getByText(/1 other session is still blocked/)).toBeInTheDocument();
  });

  it("a kind chip reports its selection instead of filtering internally", () => {
    // Controlled: the page owns the filter so it survives a tab switch.
    const setKind = vi.fn();
    const { container } = render(<WaitingTab rows={QUEUE} kind="all" setKind={setKind} now={NOW} />);
    const chips = within(container).getByText("asking");
    fireEvent.click(chips);
    expect(setKind).toHaveBeenCalledWith("ask");
    // …and it did NOT filter itself.
    expect(container.innerHTML).toContain("alpha:engine");
  });

  it("counts the queue depth on the tiles, so the backlog is visible without reading rows", () => {
    render(<WaitingTab rows={QUEUE} now={NOW} />);
    expect(screen.getByText("blocked")).toBeInTheDocument();
    expect(screen.getByText("questions")).toBeInTheDocument();
  });
});
